CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE FUNCTION auth.role() RETURNS text LANGUAGE sql AS $$ SELECT coalesce(nullif(current_setting('request.jwt.claim.role',true),''),'authenticated') $$;
CREATE TABLE employees(id uuid PRIMARY KEY,auth_user_id uuid,is_active boolean DEFAULT true,role text,access_level text,permissions text[],is_sales_team_manager boolean DEFAULT false,sales_team_id uuid);
CREATE TABLE events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text,description text,event_date timestamptz,location text,status text,budget numeric,expected_revenue numeric,organization_id uuid,contact_person_id uuid,category_id uuid,my_company_id uuid,created_by uuid,financial_source text,accepted_calculation_id uuid,has_equipment_shortage boolean,updated_at timestamptz);
CREATE TABLE tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text,description text,priority text,status text,board_column text,order_index int,created_by uuid,is_private boolean,is_inquiry boolean DEFAULT false,inquiry_stage text,inquiry_owner_id uuid,inquiry_details jsonb DEFAULT '{}',next_action_at timestamptz,last_contact_at timestamptz,updated_at timestamptz,created_at timestamptz DEFAULT now(),linked_offer_id uuid,event_id uuid,inquiry_id uuid,due_date timestamptz,estimated_value numeric,organization_id uuid,contact_id uuid,lost_reason text,assigned_to uuid);
CREATE TABLE offers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),inquiry_id uuid,event_id uuid,created_by uuid,offer_number text UNIQUE,title text,status text,package_mode boolean DEFAULT false,created_at timestamptz DEFAULT now(),updated_at timestamptz,accepted_at timestamptz,accepted_package_id uuid,accepted_variant_selections jsonb NOT NULL DEFAULT '[]',sent_at timestamptz,generated_pdf_url text,last_generated_at timestamptz,last_generated_by uuid,modified_after_generation boolean,subtotal numeric DEFAULT 0,total_amount numeric DEFAULT 0,discount_amount numeric DEFAULT 0);
CREATE TABLE offer_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),offer_id uuid REFERENCES offers(id),product_id uuid,product_variant_id uuid,name text,quantity numeric,unit_price numeric,display_order int,created_at timestamptz,updated_at timestamptz,subtotal numeric GENERATED ALWAYS AS (quantity*unit_price) STORED);
CREATE TABLE offer_packages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),offer_id uuid REFERENCES offers(id),name text,price_net numeric DEFAULT 0,display_order int,created_at timestamptz,updated_at timestamptz);
CREATE TABLE offer_package_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),package_id uuid REFERENCES offer_packages(id),offer_item_id uuid REFERENCES offer_items(id),product_id uuid,product_variant_id uuid,quantity numeric,display_order int,created_at timestamptz);
CREATE TABLE offer_equipment_substitutions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),offer_id uuid REFERENCES offers(id),created_at timestamptz);
CREATE TABLE offer_product_variants(id uuid PRIMARY KEY,name text);
CREATE TABLE event_calculations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid,inquiry_id uuid,name text,notes text,created_by uuid,created_at timestamptz DEFAULT now(),updated_at timestamptz,is_accepted boolean DEFAULT false,generated_pdf_path text,generated_pdf_at timestamptz);
CREATE TABLE event_calculation_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),calculation_id uuid REFERENCES event_calculations(id),name text,quantity numeric,unit_price numeric,days numeric DEFAULT 1,position int,created_at timestamptz,updated_at timestamptz);
CREATE TABLE event_equipment(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid,offer_id uuid,equipment_id uuid,kit_id uuid,quantity numeric,reservation_status text,is_optional boolean,auto_added boolean);
CREATE TABLE inquiry_followup_schedule(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),inquiry_id uuid,status text,updated_at timestamptz);
CREATE TABLE task_assignees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_id uuid,employee_id uuid,assigned_by uuid);
CREATE TABLE contact_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text,email text,phone text,company text,message text,source_page text,status text,priority text,category text,subject text,notes text,created_at timestamptz DEFAULT now());
CREATE TABLE contact_form_submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text,email text,phone text,message text,source_page text,source_section text,city_interest text,event_type text,utm_source text,utm_medium text,utm_campaign text,referrer text,metadata jsonb,created_at timestamptz DEFAULT now());
CREATE TABLE webhook_sources(id uuid PRIMARY KEY,name text,slug text);
CREATE TABLE inbound_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_id uuid,external_event_id text,event_type text,title text,body text,detail_url text,event_time timestamptz,metadata jsonb,created_at timestamptz DEFAULT now());
CREATE TABLE marketing_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),message_preview text,sender_name text);
CREATE FUNCTION current_employee_can_access_company(uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT true $$;
CREATE FUNCTION current_employee_can_access_event_company(uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT true $$;
CREATE FUNCTION is_inquiry_admin() RETURNS boolean LANGUAGE sql AS $$ SELECT EXISTS(SELECT 1 FROM employees WHERE id=auth.uid() AND role='admin') $$;
CREATE FUNCTION has_inquiry_permission(text) RETURNS boolean LANGUAGE sql AS $$ SELECT EXISTS(SELECT 1 FROM employees WHERE id=auth.uid() AND $1=ANY(permissions)) $$;
CREATE FUNCTION get_offer_selected_equipment(uuid,uuid) RETURNS TABLE(item_type text,item_id uuid,qty integer) LANGUAGE sql AS $$ SELECT 'item','00000000-0000-0000-0000-000000000111'::uuid,1 $$;
CREATE FUNCTION generate_offer_number(uuid) RETURNS text LANGUAGE sql AS $$ SELECT 'OF/'||gen_random_uuid()::text $$;
